UPDATE public.blogs SET content = replace(content, $o$<p>Zahvale, uređenje groba i spomenik, sortiranje osobnih stvari te prikupljanje fotografija i uspomena mogu pričekati tjednima nakon ispraćaja.</p>$o$, $n$<p>Zahvale, uređenje groba i spomenik, sortiranje osobnih stvari te prikupljanje fotografija i uspomena mogu pričekati tjednima nakon ispraćaja. Za uređenje groba pogledajte <a href="/blog/aranzmani-za-groblje">ideje za aranžmane za groblje</a>, a za zahvale i odgovore na poruke <a href="/blog/iskrena-sucut-tekstovi-poruke">primjere tekstova sućuti</a>.</p>$n$) WHERE slug = 'kako-organizirati-sprovod' AND position($h$ Za uređenje groba pogledajte <a href="/blog/aranzmani-za-groblje">ideje za aranžmane za groblje</a>, a za zahvale i odgovore na poruke <a href="/blog/iskrena-sucut-tekstovi-poruke">primjere tekstova sućuti</a>.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p>U prvim tjednima obveze se gomilaju, od dokumenata do kućanskih poslova. Kada netko ponudi pomoć, recite konkretno što vam treba – kupovina, kuhanje ili vožnja.</p>$o$, $n$<p>U prvim tjednima obveze se gomilaju, od dokumenata do kućanskih poslova. Kada netko ponudi pomoć, recite konkretno što vam treba – kupovina, kuhanje ili vožnja. Jedna od prvih je zahtjev za obiteljsku mirovinu, a uvjete i rokove objasnili smo u članku <a href="/blog/nasljedivanje-mirovine-od-supruga">nasljeđivanje mirovine od supruga</a>.</p>$n$) WHERE slug = 'kako-preboljeti-gubitak-supruga' AND position($h$ Jedna od prvih je zahtjev za obiteljsku mirovinu, a uvjete i rokove objasnili smo u članku <a href="/blog/nasljedivanje-mirovine-od-supruga">nasljeđivanje mirovine od supruga</a>.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p>Neke obitelji tada zapale svijeću, posjete grob ili zajedno pogledaju fotografije. Možete i <a href="/zapali-svijecu">zapaliti virtualnu svijeću</a> ako ste daleko od groba.</p>$o$, $n$<p>Neke obitelji tada zapale svijeću, posjete grob ili zajedno pogledaju fotografije. Možete i <a href="/zapali-svijecu">zapaliti virtualnu svijeću</a> ako ste daleko od groba. Ako grob uređujete za Svi svete, pripremili smo i <a href="/blog/aranzmani-za-groblje">ideje za aranžmane za groblje</a>.</p>$n$) WHERE slug = 'kako-preboljeti-gubitak-supruga' AND position($h$ Ako grob uređujete za Svi svete, pripremili smo i <a href="/blog/aranzmani-za-groblje">ideje za aranžmane za groblje</a>.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p>Ovisno o statusu pokojnika, obitelj može imati pravo na naknadu pogrebnih troškova, primjerice kroz mirovinsko osiguranje, poslodavca ili socijalnu skrb. Uvjeti se mijenjaju, pa ih <strong>provjerite izravno kod nadležne ustanove</strong>.</p>$o$, $n$<p>Ovisno o statusu pokojnika, obitelj može imati pravo na naknadu pogrebnih troškova, primjerice kroz mirovinsko osiguranje, poslodavca ili socijalnu skrb. Uvjeti se mijenjaju, pa ih <strong>provjerite izravno kod nadležne ustanove</strong>. Ako je preminuo supružnik, provjerite i <a href="/blog/nasljedivanje-mirovine-od-supruga">pravo na obiteljsku mirovinu</a>.</p>$n$) WHERE slug = 'troskovi-pogreba' AND position($h$ Ako je preminuo supružnik, provjerite i <a href="/blog/nasljedivanje-mirovine-od-supruga">pravo na obiteljsku mirovinu</a>.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p><a href="/blog/smrtni-list">Smrtni list</a> izdaje matični ured. Zatražite nekoliko primjeraka jer će vam trebati za banke, mirovinsko i ostavinu.</p>$o$, $n$<p><a href="/blog/smrtni-list">Smrtni list</a> izdaje matični ured. Zatražite nekoliko primjeraka jer će vam trebati za banke, mirovinsko i ostavinu. Ako je preminuo supružnik, trebat će vam i za <a href="/blog/nasljedivanje-mirovine-od-supruga">zahtjev za obiteljsku mirovinu</a>.</p>$n$) WHERE slug = 'postupak-kod-smrtnog-slucaja' AND position($h$ Ako je preminuo supružnik, trebat će vam i za <a href="/blog/nasljedivanje-mirovine-od-supruga">zahtjev za obiteljsku mirovinu</a>.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<li><strong>Ostavinski postupak</strong> – pokreće se po službenoj dužnosti, javni bilježnik će vas pozvati. Više u članku <a href="/blog/ostavinska-rasprava-koji-dokumenti-su-nam-potrebni">Ostavinska rasprava</a>.</li>$o$, $n$<li><strong>Ostavinski postupak</strong> – pokreće se po službenoj dužnosti, javni bilježnik će vas pozvati. Više u članku <a href="/blog/ostavinska-rasprava-koji-dokumenti-su-nam-potrebni">Ostavinska rasprava</a>. Imovina koju je pokojnik za života prenio <a href="/blog/ugovor-o-dozivotnom-uzdrzavanju">ugovorom o doživotnom uzdržavanju</a> u pravilu ne ulazi u ostavinu.</li>$n$) WHERE slug = 'postupak-kod-smrtnog-slucaja' AND position($h$ Imovina koju je pokojnik za života prenio <a href="/blog/ugovor-o-dozivotnom-uzdrzavanju">ugovorom o doživotnom uzdržavanju</a> u pravilu ne ulazi u ostavinu.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p>Nakon smrti bliske osobe, uz tugu dolaze i pravne obveze. Jedna od njih je ostavinski postupak, u kojem se utvrđuje tko nasljeđuje imovinu pokojnika.</p>$o$, $n$<p>Nakon smrti bliske osobe, uz tugu dolaze i pravne obveze. Jedna od njih je ostavinski postupak, u kojem se utvrđuje tko nasljeđuje imovinu pokojnika. Imovina koju je pokojnik za života prenio <a href="/blog/ugovor-o-dozivotnom-uzdrzavanju">ugovorom o doživotnom uzdržavanju</a> u pravilu nije dio ostavine.</p>$n$) WHERE slug = 'ostavinska-rasprava-koji-dokumenti-su-nam-potrebni' AND position($h$ Imovina koju je pokojnik za života prenio <a href="/blog/ugovor-o-dozivotnom-uzdrzavanju">ugovorom o doživotnom uzdržavanju</a> u pravilu nije dio ostavine.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p>Zasigurno bi im bilo drago da se nakon ovog tužnog događaja ne moraju brinuti i o raspodjeli imovine. Pisanje oporuke se možda čini kao zahtjevna aktivnost i možda ne znate kako biste započeli, ali samo razmišljanje o tome koliko ćete svojim bližnjima olakšati ove tužne dane napisanom oporukom trebalo bi biti dovoljno da se svatko odluči na ovaj korak.</p>$o$, $n$<p>Zasigurno bi im bilo drago da se nakon ovog tužnog događaja ne moraju brinuti i o raspodjeli imovine. Pisanje oporuke se možda čini kao zahtjevna aktivnost i možda ne znate kako biste započeli, ali samo razmišljanje o tome koliko ćete svojim bližnjima olakšati ove tužne dane napisanom oporukom trebalo bi biti dovoljno da se svatko odluči na ovaj korak. Ako uz raspodjelu imovine želite osigurati i skrb u starosti, usporedite oporuku s <a href="/blog/ugovor-o-dozivotnom-uzdrzavanju">ugovorom o doživotnom uzdržavanju</a>.</p>$n$) WHERE slug = 'kako-napisati-oporuku' AND position($h$ Ako uz raspodjelu imovine želite osigurati i skrb u starosti, usporedite oporuku s <a href="/blog/ugovor-o-dozivotnom-uzdrzavanju">ugovorom o doživotnom uzdržavanju</a>.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p>Poruka spominje pokojnika imenom, ne traži odgovor i ostavlja prostor za „ne”. Više primjera riječi sućuti naći ćete u članku o <a href="/blog/kako-se-nositi-s-tugom">nošenju s tugom</a>.</p>$o$, $n$<p>Poruka spominje pokojnika imenom, ne traži odgovor i ostavlja prostor za „ne”. Više primjera riječi sućuti naći ćete u članku o <a href="/blog/kako-se-nositi-s-tugom">nošenju s tugom</a>. Gotove primjere za prijatelje, kolege i obitelj složili smo u članku <a href="/blog/iskrena-sucut-tekstovi-poruke">iskrena sućut: tekstovi i SMS poruke</a>.</p>$n$) WHERE slug = 'kako-pruziti-podrsku-ozaloscenoj-osobi' AND position($h$ Gotove primjere za prijatelje, kolege i obitelj složili smo u članku <a href="/blog/iskrena-sucut-tekstovi-poruke">iskrena sućut: tekstovi i SMS poruke</a>.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p>Ljudi će se rijetko sjećati što ste nosili, ali će se sjećati jesu li vas vidjeli. Kratka rečenica sućuti i stisak ruke često znače više od bilo čega drugog.</p>$o$, $n$<p>Ljudi će se rijetko sjećati što ste nosili, ali će se sjećati jesu li vas vidjeli. Kratka rečenica sućuti i stisak ruke često znače više od bilo čega drugog. Ako ne znate što reći, pogledajte <a href="/blog/iskrena-sucut-tekstovi-poruke">primjere iskrene sućuti</a>.</p>$n$) WHERE slug = 'kako-se-obuci-za-sprovod' AND position($h$ Ako ne znate što reći, pogledajte <a href="/blog/iskrena-sucut-tekstovi-poruke">primjere iskrene sućuti</a>.$h$ in content) = 0;
UPDATE public.blogs SET content = replace(content, $o$<p><a href="https://osmrtnica.com.hr/">Osmrtnice</a> također mogu sadržavati informacije o tome gdje se može poslati cvijeće ili donacija, kao i kontakte obitelji preminulog za izražavanje sućuti ili dodatna pitanja. Provjeravanje osmrtnica može biti korisno kako biste saznali konkretne detalje o sprovodu i možda saznate više o tradicijama i protokolu koje možete očekivati na sprovodu.</p>$o$, $n$<p><a href="https://osmrtnica.com.hr/">Osmrtnice</a> također mogu sadržavati informacije o tome gdje se može poslati cvijeće ili donacija, kao i kontakte obitelji preminulog za izražavanje sućuti ili dodatna pitanja. Provjeravanje osmrtnica može biti korisno kako biste saznali konkretne detalje o sprovodu i možda saznate više o tradicijama i protokolu koje možete očekivati na sprovodu. Što napisati obitelji, pronaći ćete u našim <a href="/blog/iskrena-sucut-tekstovi-poruke">primjerima poruka sućuti</a>.</p>$n$) WHERE slug = 'trebam-li-nositi-crninu-na-sprovodu' AND position($h$ Što napisati obitelji, pronaći ćete u našim <a href="/blog/iskrena-sucut-tekstovi-poruke">primjerima poruka sućuti</a>.$h$ in content) = 0;
